            "body": "Cada ajuste cobra um preço, e quem os define é o protocolo aprovado pelo serviço. Mais mA ou mAs: menos ruído, mais dose. Só neste esquema, com o resto igual, quadruplicar a corrente dobra a relação sinal-ruído e quadruplica a dose. Mais kV: tende a menos ruído, com mais dose; kV mais baixo deixa o iodo mais visível. O CTDIvol é o CTDIw dividido pelo pitch: para o mesmo CTDIw, pitch maior dá CTDIvol menor; pitch menor traz menos artefato de interpolação. Corte mais fino: mais detalhe, mais ruído. CTDIvol e DLP indicam a saída do equipamento, não a dose do paciente.",
